commit fe6af80931c35fafc6a2cd0651b6de052d1bffae
Author: Philip Withnall <pwithnall@gnome.org>
Date:   Tue Feb 18 16:44:58 2025 +0000

    gdatetime: Fix integer overflow when parsing very long ISO8601 inputs

    This will only happen with invalid (or maliciously invalid) potential
    ISO8601 strings, but `g_date_time_new_from_iso8601()` needs to be robust
    against that.

    Prevent `length` overflowing by correctly defining it as a `size_t`.
    Similarly for `date_length`, but additionally track its validity in a
    boolean rather than as its sign.

    Spotted by chamalsl as #YWH-PGM9867-43.

    Signed-off-by: Philip Withnall <pwithnall@gnome.org>

diff --git a/glib/gdatetime.c b/glib/gdatetime.c
index ad9c190b6..b33db2c20 100644
--- a/glib/gdatetime.c
+++ b/glib/gdatetime.c
@@ -1467,176 +1467,180 @@ parse_iso8601_time (const gchar *text, gsize length,
   /* Check for timezone suffix */
   *tz = parse_iso8601_timezone (text, length, &tz_offset);
   if (tz_offset >= 0)
     length = tz_offset;

   /* hh:mm:ss(.sss) */
   if (length >= 8 && text[2] == ':' && text[5] == ':')
     {
       return get_iso8601_int (text, 2, hour) &&
              get_iso8601_int (text + 3, 2, minute) &&
              get_iso8601_seconds (text + 6, length - 6, seconds);
     }
   /* hhmmss(.sss) */
   else if (length >= 6)
     {
       return get_iso8601_int (text, 2, hour) &&
              get_iso8601_int (text + 2, 2, minute) &&
              get_iso8601_seconds (text + 4, length - 4, seconds);
     }
   else
     return FALSE;
 }

 /**
  * g_date_time_new_from_iso8601: (constructor)
  * @text: an ISO 8601 formatted time string.
  * @default_tz: (nullable): a #GTimeZone to use if the text doesn't contain a
  *                          timezone, or %NULL.
  *
  * Creates a #GDateTime corresponding to the given
  * [ISO 8601 formatted string](https://en.wikipedia.org/wiki/ISO_8601)
  * @text. ISO 8601 strings of the form `<date><sep><time><tz>` are supported, with
  * some extensions from [RFC 3339](https://tools.ietf.org/html/rfc3339) as
  * mentioned below.
  *
  * Note that as #GDateTime "is oblivious to leap seconds", leap seconds information
  * in an ISO-8601 string will be ignored, so a `23:59:60` time would be parsed as
  * `23:59:59`.
  *
  * `<sep>` is the separator and can be either 'T', 't' or ' '. The latter two
  * separators are an extension from
  * [RFC 3339](https://tools.ietf.org/html/rfc3339#section-5.6).
  *
  * `<date>` is in the form:
  *
  * - `YYYY-MM-DD` - Year/month/day, e.g. 2016-08-24.
  * - `YYYYMMDD` - Same as above without dividers.
  * - `YYYY-DDD` - Ordinal day where DDD is from 001 to 366, e.g. 2016-237.
  * - `YYYYDDD` - Same as above without dividers.
  * - `YYYY-Www-D` - Week day where ww is from 01 to 52 and D from 1-7,
  *   e.g. 2016-W34-3.
  * - `YYYYWwwD` - Same as above without dividers.
  *
  * `<time>` is in the form:
  *
  * - `hh:mm:ss(.sss)` - Hours, minutes, seconds (subseconds), e.g. 22:10:42.123.
  * - `hhmmss(.sss)` - Same as above without dividers.
  *
  * `<tz>` is an optional timezone suffix of the form:
  *
  * - `Z` - UTC.
  * - `+hh:mm` or `-hh:mm` - Offset from UTC in hours and minutes, e.g. +12:00.
  * - `+hh` or `-hh` - Offset from UTC in hours, e.g. +12.
  *
